SELECT COUNT(*)
FROM (
    SELECT 1
    FROM video_status_outbox
    WHERE status = #{status}
    LIMIT #{cap}
) capped

SELECT COUNT(*)
FROM (
    SELECT 1
    FROM video_status_consumed_event
    WHERE process_status = #{processStatus}
    LIMIT #{cap}
) capped

SELECT COUNT(*)
FROM information_schema.statistics
WHERE table_schema = DATABASE()
  AND table_name = #{tableName}
  AND index_name = #{indexName}
